// pxl-tool/spec/cmd.rs

//! The core's manifest, and its link's bindings from spec/client/core/wit/,
//! generated by xpute's generator.

use xpute_gen::spec::manifest;
use xpute_gen::spec::wit::{wit_outputs, WitTarget};

use super::Output;
use crate::root;

pub fn outputs() -> Result<Vec<Output>, String> {
    let mut out = manifest::outputs(&root(), "spec/client/core/sys/manifest.json")?;
    out.extend(wit_outputs(
        &root(),
        &WitTarget {
            dirs: &["xpute/wit", "xpute/wit/gpu", "spec/client/core/wit"],
            rs: Some(("rust/client/core/src/abi.rs", "pxl-core/abi.rs")),
            ts: Some(("ts/client/src/abi", "@pxl/client/abi")),
            core: "xpute_core",
            runtime_ts: "@xpute/runtime",
            externs: &[
                ("xpute:core", "xpute_core::abi", "@xpute/runtime/abi"),
                ("xpute:gpu", "xpute_gpu::abi", "@xpute/gpu/abi"),
            ],
        },
    )?);
    Ok(out)
}
